1	package ociresources
2	
3	import (
4		"strings"
5	
6		"charm.land/lipgloss/v2"
7	
8		"github.com/anthnel/devdesk/internal/jobs"
9		"github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/theme"
11	)
12	
13	// rebuildTagTable re-decorates the rows and hands them to the table.
14	//
15	// The decoration — the scan counts, whether a scan is running, the registry's
16	// label — is not on the tag, and the columns are built once so they cannot
17	// reach the browser for it. So it is recomputed wholesale on every change,
18	// exactly as the images tab does with imageRow.
19	//
20	// The filters are applied here because they narrow the tags before the table
21	// sees them; the sort and the header arrows are the table's.
22	func (b *RegistryBrowser) rebuildTagTable() {
23		tags := b.filteredMultiTags()
24	
25		rows := make([]tagRow, len(tags))
26		for i, t := range tags {
27			imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
28			label := t.Alias
29			if label == "" {
30				label = t.RegistryURL
31			}
32			entry, scanned := b.scanCache[imageName]
33			rows[i] = tagRow{
34				tag:         t,
35				label:       label,
36				entry:       entry,
37				scanned:     scanned,
38				Activity:    b.tagActivity(imageName),
39				ScanRunning: b.scanRunning(imageName),
40			}
41		}
42	
43		b.tagTable.SetItems(rows)
44		b.resizeTables()
45	}
46	
47	// tagActivity resolves what one tag row says about its activity: a scan or a
48	// pull, whoever started it, or a remembered failure of either. Both are read
49	// against the context the snapshot carries, with the raw reference as identity.
50	func (b *RegistryBrowser) tagActivity(imageName string) components.RowActivity {
51		return components.DescribeRow(components.RowQuery{
52			Runs: b.jobs, Failures: b.failures, Context: b.contextName,
53			Target: jobs.TargetKey(imageName), Kinds: ociKinds,
54		})
55	}
56	
57	// scanRunning reports whether a scan of the tag runs now. A queued scan does
58	// not: it keeps its counts.
59	func (b *RegistryBrowser) scanRunning(imageName string) bool {
60		for _, a := range jobs.ActiveOn(b.jobs, b.contextName, imageName, jobs.KindScan) {
61			if a.Item.State == jobs.ItemRunning {
62				return true
63			}
64		}
65		return false
66	}
67	
68	// View renders the browser for the current state.
69	func (b *RegistryBrowser) View() string {
70		switch b.state {
71		case browserStateTags:
72			return b.viewTags()
73		case browserStateImages:
74			return b.searchTable.View()
75		default:
76			return b.viewInput()
77		}
78	}
79	
80	func (b *RegistryBrowser) viewInput() string {
81		var sb strings.Builder
82	
83		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
84		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
85		sb.WriteString("\n\n")
86	
87		if len(b.rows) > 0 {
88			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
89			for i, row := range b.rows {
90				focused := b.focusedField == b.brFieldReg(i)
91				if row.groupSlug != "" {
92					// One checkbox for the whole group, with a third state for a
93					// partial selection — eight proxies are not eight keystrokes.
94					sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
95				} else {
96					sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
97				}
98				if i < len(b.rows)-1 {
99					sb.WriteString("\n")
100				}
101			}
102			sb.WriteString("\n\n")
103		}
104	
105		sb.WriteString(b.renderFormButtons())
106	
107		return sb.String()
108	}
109	
110	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
111		var labelStr string
112		if b.focusedField == fieldIdx {
113			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
114		} else {
115			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
116		}
117		return labelStr + "\n  " + value
118	}
119	
120	// viewTags renders the tag table. The search says so in the footer, with the
121	// shared activity dot (LoadingLabel), and an empty table stays a table (Rule 139) — the
122	// count lives in GetHeaderInfo's "Tags" field.
123	func (b *RegistryBrowser) viewTags() string {
124		return b.tagTable.View()
125	}
126	
127	// LoadingLabel names what the browser is fetching, for the OCI view's footer.
128	// The second result is false when nothing is in flight.
129	func (b *RegistryBrowser) LoadingLabel() (string, bool) {
130		if (b.state == browserStateTags || b.state == browserStateImages) && b.pendingSearches > 0 {
131			return "Searching registries...", true
132		}
133		return "", false
134	}
135	
136	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
137	func (b *RegistryBrowser) FilterIsVisible() bool {
138		if b.state == browserStateImages {
139			return b.searchTable.FilterBar().IsVisible()
140		}
141		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
142	}
143	
144	// FilterBarView renders the filter bar (2 lines) for display in the footer.
145	func (b *RegistryBrowser) FilterBarView(width int) string {
146		if b.state == browserStateImages {
147			return b.searchTable.FilterBar().View()
148		}
149		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
150	
151		var left string
152		if b.filterActive {
153			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
154		} else if b.filterInput.Value() != "" {
155			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
156		} else {
157			left = theme.DimStyle.Render("/ filter…")
158		}
159	
160		if !b.registryFilter.isEmpty() {
161			left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
162		}
163	
164		inner := theme.Bg(" ") + left
165		paddedInner := theme.PadWithBg(inner, width-2)
166		contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
167		bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
168		return contentLine + "\n" + bottomBorder
169	}
170	
171	// viewStatus is gone with browserStateStatus (§3.60). It was a
172	// loading message filling the panel — the shape Rule 139 keeps out of a
173	// table body — and what it announced is now a row in the Images tab.
174

