1	package ociresources
2	
3	import (
4		"errors"
5		"log"
6		"net/url"
7		"strconv"
8		"strings"
9	
10		tea "charm.land/bubbletea/v2"
11		"charm.land/lipgloss/v2"
12	
13		"github.com/anthnel/devdesk/internal/imagesearch"
14		"github.com/anthnel/devdesk/internal/jobs"
15		"github.com/anthnel/devdesk/internal/oci"
16		"github.com/anthnel/devdesk/internal/ui/datatable"
17		"github.com/anthnel/devdesk/internal/ui/indicator"
18		"github.com/anthnel/devdesk/internal/ui/shortcut"
19		"github.com/anthnel/devdesk/internal/ui/theme"
20	)
21	
22	// searchRow is one line of the level 1 table: an image, and the label of the
23	// registry that returned it.
24	type searchRow struct {
25		img   imagesearch.Image
26		label string
27		// ref is the full reference (host/repo), what the footer describes.
28		ref string
29	}
30	
31	// searchRowReference returns the full reference of an image found in the
32	// registry at registryURL: the host, then the final repository path. Docker
33	// Hub is always written docker.io, whichever spelling it is configured under.
34	func searchRowReference(registryURL string, img imagesearch.Image) string {
35		host := oci.RegistryHost(registryURL)
36		if host == "" {
37			return img.Repo
38		}
39		if oci.IsDockerHub(registryURL) {
40			host = "docker.io"
41		}
42		return host + "/" + img.Repo
43	}
44	
45	// searchColumns describes the level 1 table. Stars, Official and Description
46	// leave whole when the terminal narrows, in that reverse order (Description,
47	// Stars, Official), through Optional and DropFirst: drop() takes the rightmost
48	// DropFirst column first, then the rightmost Optional one.
49	func searchColumns() []datatable.Column[searchRow] {
50		return []datatable.Column[searchRow]{
51			datatable.IndicatorColumn(
52				func(searchRow) indicator.State { return indicator.Idle },
53				func(searchRow) string { return theme.IconDocker },
54				func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
55			),
56			{
57				Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
58				Cell:   func(r searchRow) string { return r.img.Name },
59				Search: func(r searchRow) string { return r.img.Name },
60			},
61			{
62				Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
63				Cell: func(r searchRow) string { return r.label },
64			},
65			{
66				Title: "Stars", Sizing: datatable.SizingFixed, Optional: true, DropFirst: true, MinWidth: 6,
67				Cell: func(r searchRow) string {
68					if !r.img.HasStars {
69						return ""
70					}
71					return strconv.Itoa(r.img.Stars)
72				},
73			},
74			{
75				Title: "Official", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10,
76				Cell: func(r searchRow) string {
77					if r.img.Official {
78						return "official"
79					}
80					return ""
81				},
82			},
83			{
84				Title: "Description", Sizing: datatable.SizingContent, Optional: true, DropFirst: true,
85				MinWidth: 20, Flex: 2,
86				Cell:   func(r searchRow) string { return r.img.Description },
87				Search: func(r searchRow) string { return r.img.Description },
88			},
89		}
90	}
91	
92	// newSearchTable builds the level 1 table; rebuildSearchTable orders its rows.
93	func newSearchTable() *datatable.Model[searchRow] {
94		t := datatable.New(datatable.Config[searchRow]{
95			Columns:    searchColumns(),
96			SortColumn: -1,
97		})
98		return &t
99	}
100	
101	// rebuildSearchTable hands the collected images to the table.
102	func (b *RegistryBrowser) rebuildSearchTable() {
103		rows := make([]searchRow, len(b.images))
104		for i, img := range b.images {
105			label, ref := "", img.Repo
106			if e := b.entryFor(img.EntryKey); e != nil {
107				label = entryAlias(*e)
108				if label == "" {
109					label = e.URL
110				}
111				ref = searchRowReference(e.URL, img)
112			}
113			rows[i] = searchRow{img: img, label: label, ref: ref}
114		}
115		sortSearchRows(b.searchQuery, rows)
116		// The cursor follows the selected row by (EntryKey, Repo), not by index:
117		// rows of another registry land before or after it. Nothing selected (an
118		// empty table, so also a new search) goes to the first row, because an
119		// empty table keeps its old cursor index; a vanished row stays put.
120		prev, hadSel := b.searchTable.Selected()
121		b.searchTable.SetItems(rows)
122		if !hadSel {
123			b.searchTable.GotoTop()
124		} else {
125			for i, r := range b.searchTable.Visible() {
126				if r.img.EntryKey == prev.img.EntryKey && r.img.Repo == prev.img.Repo {
127					b.searchTable.SetCursor(i)
128					break
129				}
130			}
131		}
132		b.resizeTables()
133	}
134	
135	// AddImageResults takes one registry's answer. It returns false, touching
136	// nothing, when the answer belongs to another lot. pendingSearches never goes
137	// below zero.
138	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
139		if msg.Gen != b.gen {
140			return false
141		}
142		if b.pendingSearches > 0 {
143			b.pendingSearches--
144		}
145		oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
146		if b.outcomes == nil {
147			b.outcomes = map[string]imagesearch.Outcome{}
148		}
149		b.outcomes[msg.EntryKey] = oc
150		if oc.Verdict == imagesearch.VerdictOK {
151			for _, img := range msg.Images {
152				img.EntryKey = msg.EntryKey
153				b.images = append(b.images, img)
154			}
155		}
156		b.rebuildSearchTable()
157		return true
158	}
159	
160	// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
161	// back to the form; esc acts in order: the filter bar while it is open, then a
162	// confirmed query, then it cancels the lot and goes back to the form (which
163	// keeps the typed name and the selection). The lot's late answers are no
164	// longer wanted and are dropped
165	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
166	// nothing: a row has no action yet; → opens the row's tags.
167	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
168		if b.searchTable.InEditMode() {
169			return b, b.searchTable.Update(msg)
170		}
171		switch msg.String() {
172		case "right":
173			return b.openSelectedImageTags()
174		case "esc":
175			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
176				bar.ClearSearch()
177				b.searchTable.SetItems(b.searchTable.Items())
178				return b, nil
179			}
180			return b.backToForm()
181		case "left":
182			return b.backToForm()
183		case "enter":
184			return b, nil
185		}
186		return b, b.searchTable.Update(msg)
187	}
188	
189	// backToForm cancels the lot and returns to the form, which keeps the typed
190	// name and the selection. Late answers of the lot are dropped.
191	func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
192		b.abandonLot()
193		b.state = browserStateInput
194		b.searchTable.Blur()
195		b.updateFocus()
196		return b, nil
197	}
198	
199	// handleImageSearchResult records one registry's answer; a stale one is ignored.
200	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
201		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
202			return m, nil
203		}
204		oc, _ := m.registryBrowser.Outcome(msg.EntryKey)
205		alias := msg.EntryKey
206		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
207			alias = entryAlias(*e)
208		}
209		logSearchOutcome(alias, oc, msg.Err)
210		return m, nil
211	}
212	
213	// logSearchOutcome logs a registry's verdict: failed as an error, refused as
214	// info, nothing for ok or no result. The cause goes through searchErrorCause,
215	// so no secret or typed text reaches the log.
216	func logSearchOutcome(alias string, oc imagesearch.Outcome, err error) {
217		switch oc.Verdict {
218		case imagesearch.VerdictFailed:
219			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(err))
220		case imagesearch.VerdictRefused:
221			log.Printf("INFO [oci_resources] image search on %s: unsupported or refused: %s", alias, searchErrorCause(err))
222		}
223	}
224	
225	// searchErrorCause is the loggable text of a search error. A *url.Error holds
226	// the full request URL, which carries the text the user typed, so only its Op
227	// and Err are kept.
228	func searchErrorCause(err error) string {
229		var ue *url.Error
230		if errors.As(err, &ue) {
231			return jobs.SafeCause(errors.New(ue.Op + ": " + jobs.SafeCause(ue.Err)))
232		}
233		return jobs.SafeCause(err)
234	}
235	
236	// handleRegistryBrowserWarn shows the browser's warning in the footer.
237	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
238		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
239	}
240	
241	// tagsLoadFailedText is the footer text of a failed tag listing opened by →.
242	const tagsLoadFailedText = "Could not load tags"
243	
244	// selectedImage returns the level 1 row under the cursor with its registry
245	// entry; false when there is no row or the entry is no longer known.
246	func (b *RegistryBrowser) selectedImage() (searchRow, *browserRegistryEntry, bool) {
247		row, ok := b.searchTable.Selected()
248		if !ok {
249			return searchRow{}, nil, false
250		}
251		entry := b.entryFor(row.img.EntryKey)
252		return row, entry, entry != nil
253	}
254	
255	// imageDrillIn reports whether → has an image to open: a row under the cursor
256	// whose registry entry is still known. One computation for the header and the
257	// handler (Rule 130).
258	func (b *RegistryBrowser) imageDrillIn() shortcut.Availability {
259		if _, _, ok := b.selectedImage(); !ok {
260			return shortcut.Unavailable(reasonNoImage)
261		}
262		return shortcut.Availability{}
263	}
264	
265	// openSelectedImageTags lists the tags of the selected level 1 row, on that
266	// row's registry only, with the row's final repository as is (no prefix, no
267	// library/ added again). Without a row it changes nothing and warns. A level 1
268	// search still running is cancelled: the browser has one lot at a time.
269	func (b *RegistryBrowser) openSelectedImageTags() (*RegistryBrowser, tea.Cmd) {
270		if av := b.imageDrillIn(); !av.Enabled() {
271			reason := av.Reason
272			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: reason} }
273		}
274		row, entry, _ := b.selectedImage()
275		b, cmd := b.startTagRequests([]tagRequest{b.newTagRequest(*entry, row.img.Repo)}, true)
276		b.tagsImage = row.img.Name
277		return b, cmd
278	}
279	
280	// Outcome returns the verdict of entryKey in the current lot; false while
281	// pending.
282	func (b *RegistryBrowser) Outcome(entryKey string) (imagesearch.Outcome, bool) {
283		oc, ok := b.outcomes[entryKey]
284		return oc, ok
285	}
