1	package ociresources
2	
3	import (
4		"slices"
5		"time"
6	
7		"github.com/anthnel/devdesk/internal/cache"
8		"github.com/anthnel/devdesk/internal/jobs"
9		"github.com/anthnel/devdesk/internal/ui/indicator"
10	)
11	
12	// AddRegistryTags incorporates results from one registry into the combined tag list.
13	// Always decrements pendingSearches, even on error (tags will be nil).
14	func (b *RegistryBrowser) AddRegistryTags(entryKey, registryURL, alias, repo string, tags []string) {
15		// Floored: a duplicate or late response would otherwise drive the counter
16		// negative, and the next search would start from that base — IsSearching()
17		// would stay false while requests were genuinely in flight, so the spinner
18		// never showed.
19		if b.pendingSearches > 0 {
20			b.pendingSearches--
21		}
22		for _, tag := range tags {
23			b.tags = append(b.tags, MultiRegistryTag{
24				EntryKey:    entryKey,
25				RegistryURL: registryURL,
26				Alias:       alias,
27				Repo:        repo,
28				Tag:         tag,
29			})
30		}
31		if b.state == browserStateTags {
32			b.rebuildTagTable()
33		}
34	}
35	
36	// SetMultiTagsMeta stores last-updated metadata for tags belonging to one entry.
37	//
38	// Keyed on the entry, not the host: several entries share one host once a
39	// registry is a host plus a repo prefix, so a URL would stamp one proxy's dates
40	// onto every proxy of that instance (§3.18).
41	func (b *RegistryBrowser) SetMultiTagsMeta(entryKey string, meta map[string]time.Time) {
42		for i := range b.tags {
43			if b.tags[i].EntryKey != entryKey {
44				continue
45			}
46			if t, ok := meta[b.tags[i].Tag]; ok {
47				b.tags[i].UpdatedAt = t
48			}
49		}
50		if b.state == browserStateTags {
51			b.rebuildTagTable()
52		}
53	}
54	
55	// SetJobs takes the router's snapshot — what is running or remembered as
56	// failed, and the context it is read in — and rebuilds the rows.
57	//
58	// A snapshot rather than one name at a time: it says what is running rather
59	// than what changed, and reconciling a whole answer against per-name edits is
60	// how the two drift.
61	func (b *RegistryBrowser) SetJobs(runs []jobs.Run, failures []jobs.Failure, context string) {
62		b.jobs = runs
63		b.failures = slices.Clone(failures)
64		b.contextName = context
65		if b.state == browserStateTags {
66			b.rebuildTagTable()
67		}
68	}
69	
70	// SetBlinkPhase hands the router's blink phase to both tables. Nothing is
71	// rebuilt: the table reads the phase at render.
72	func (b *RegistryBrowser) SetBlinkPhase(on bool) {
73		b.tagTable.SetBlinkPhase(on)
74		b.searchTable.SetBlinkPhase(on)
75	}
76	
77	// WantsBlink reports whether a visible tag row has a running operation.
78	func (b *RegistryBrowser) WantsBlink() bool {
79		if b.state != browserStateTags {
80			return false
81		}
82		for _, r := range b.tagTable.Items() {
83			if r.Activity.State == indicator.Running {
84				return true
85			}
86		}
87		return false
88	}
89	
90	// HasSelectedTagScanResults returns true when the selected tag has cached scan results.
91	func (b *RegistryBrowser) HasSelectedTagScanResults() bool {
92		name := b.selectedImageName()
93		if name == "" {
94			return false
95		}
96		_, ok := b.scanCache[name]
97		return ok
98	}
99	
100	// SetScanCache stores the model's scan cache for CVE column display.
101	func (b *RegistryBrowser) SetScanCache(sc map[string]cache.ImageScanEntry) {
102		b.scanCache = sc
103		if b.state == browserStateTags {
104			b.rebuildTagTable()
105		}
106	}
107	
108	// SetOperationError, SetOperationSuccess and OperationImageName went with the
109	// status screen (§3.60): the browser is closed by the time a pull answers, and
110	// the answer goes to the footer and the Images list.
111	
112	// selectedImageName returns the full image reference for the focused table row.
113	func (b *RegistryBrowser) selectedImageName() string {
114		t := b.getSelectedMultiTag()
115		if t == nil {
116			return ""
117		}
118		return multiImageName(t.RegistryURL, t.Repo, t.Tag)
119	}
120	
121	// getSelectedMultiTag returns the MultiRegistryTag under the cursor, or nil.
122	//
123	// It used to replay the filter and the sort to map the cursor back to a tag,
124	// with nothing tying that ordering to the one the rows were built from. The
125	// table keeps the ordered slice it drew, so the two cannot disagree.
126	func (b *RegistryBrowser) getSelectedMultiTag() *MultiRegistryTag {
127		row, ok := b.tagTable.Selected()
128		if !ok {
129			return nil
130		}
131		return &row.tag
132	}
