13	// rebuildTagTable re-decorates the rows and hands them to the table.
14	//
15	// The decoration — the scan counts, whether a scan is running, the registry's
16	// label — is not on the tag, and the columns are built once so they cannot
17	// reach the browser for it. So it is recomputed wholesale on every change,
18	// exactly as the images tab does with imageRow.
19	//
20	// The filters are applied here because they narrow the tags before the table
21	// sees them; the sort and the header arrows are the table's.
22	func (b *RegistryBrowser) rebuildTagTable() {
23		tags := b.filteredMultiTags()
24	
25		rows := make([]tagRow, len(tags))
26		for i, t := range tags {
27			imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
28			label := t.Alias
29			if label == "" {
30				label = t.RegistryURL
31			}
32			entry, scanned := b.scanCache[imageName]
33			rows[i] = tagRow{
34				tag:         t,
35				label:       label,
36				entry:       entry,
37				scanned:     scanned,
38				Activity:    b.tagActivity(imageName),
39				ScanRunning: b.scanRunning(imageName),
40			}
41		}
42	
43		b.tagTable.SetItems(rows)
44		b.resizeTables()
45	}
46	
47	// tagActivity resolves what one tag row says about its activity: a scan or a
48	// pull, whoever started it, or a remembered failure of either. Both are read
49	// against the context the snapshot carries, with the raw reference as identity.
50	func (b *RegistryBrowser) tagActivity(imageName string) components.RowActivity {
51		return components.DescribeRow(components.RowQuery{
52			Runs: b.jobs, Failures: b.failures, Context: b.contextName,
53			Target: jobs.TargetKey(imageName), Kinds: ociKinds,
54		})
55	}
56	
57	// scanRunning reports whether a scan of the tag runs now. A queued scan does
58	// not: it keeps its counts.
59	func (b *RegistryBrowser) scanRunning(imageName string) bool {
60		for _, a := range jobs.ActiveOn(b.jobs, b.contextName, imageName, jobs.KindScan) {
61			if a.Item.State == jobs.ItemRunning {
62				return true
63			}
64		}
65		return false
66	}
67	
68	// View renders the browser for the current state.
69	func (b *RegistryBrowser) View() string {
70		switch b.state {
71		case browserStateTags:
72			return b.viewTags()
73		case browserStateImages:
74			return b.searchTable.View()
75		default:
76			return b.viewInput()
77		}
78	}
79	
80	func (b *RegistryBrowser) viewInput() string {
81		var sb strings.Builder
82	
83		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
84		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
85		sb.WriteString("\n\n")
86	
87		if len(b.rows) > 0 {
88			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
89			for i, row := range b.rows {
90				focused := b.focusedField == b.brFieldReg(i)
91				if row.groupSlug != "" {
92					// One checkbox for the whole group, with a third state for a
93					// partial selection — eight proxies are not eight keystrokes.
94					sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
95				} else {
96					sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
97				}
98				if i < len(b.rows)-1 {
99					sb.WriteString("\n")
100				}
101			}
102			sb.WriteString("\n\n")
103		}
104	
105		sb.WriteString(b.renderFormButtons())
106	
107		return sb.String()
108	}
109	
110	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
111		var labelStr string
112		if b.focusedField == fieldIdx {
113			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
114		} else {
115			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
116		}
117		return labelStr + "\n  " + value
118	}
119	
120	// viewTags renders the tag table. The search says so in the footer, with the
121	// shared activity dot (LoadingLabel), and an empty table stays a table (Rule 139) — the
122	// count lives in GetHeaderInfo's "Tags" field.
123	func (b *RegistryBrowser) viewTags() string {
124		return b.tagTable.View()
125	}
126	
127	// LoadingLabel names what the browser is fetching, for the OCI view's footer.
128	// The second result is false when nothing is in flight.
129	func (b *RegistryBrowser) LoadingLabel() (string, bool) {
130		if (b.state == browserStateTags || b.state == browserStateImages) && b.pendingSearches > 0 {
131			return "Searching registries...", true
132		}
133		return "", false
134	}
135	
136	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
137	func (b *RegistryBrowser) FilterIsVisible() bool {
138		if b.state == browserStateImages {
139			return b.searchTable.FilterBar().IsVisible()
140		}
141		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
142	}
143	
144	// FilterBarView renders the filter bar (2 lines) for display in the footer.
145	func (b *RegistryBrowser) FilterBarView(width int) string {
146		if b.state == browserStateImages {
147			return b.searchTable.FilterBar().View()
148		}
149		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
150	
151		var left string
152		if b.filterActive {
153			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
154		} else if b.filterInput.Value() != "" {
155			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
156		} else {
157			left = theme.DimStyle.Render("/ filter…")
158		}
159	
160		if !b.registryFilter.isEmpty() {
161			left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
162		}
163	
164		inner := theme.Bg(" ") + left
165		paddedInner := theme.PadWithBg(inner, width-2)
166		contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
167		bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
168		return contentLine + "\n" + bottomBorder
169	}
170	
171	// viewStatus is gone with browserStateStatus (§3.60). It was a
172	// loading message filling the panel — the shape Rule 139 keeps out of a
173	// table body — and what it announced is now a row in the Images tab.
174

1	package app
2	
3	import (
4		"strings"
5	
6		"charm.land/lipgloss/v2"
7		"github.com/anthnel/devdesk/internal/ui/shortcut"
8		"github.com/anthnel/devdesk/internal/ui/theme"
9		"github.com/charmbracelet/x/ansi"
10	)
11	
12	// HeaderView is the interface each view must implement to provide the header data
13	type HeaderView interface {
14		GetShortcuts() shortcut.Shortcuts
15		GetTitle() string
16		GetIcon() string
17		GetHeaderInfo(context string) []shortcut.HeaderInfo
18	}
19	
20	// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
21	// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
22	type FooterView interface {
23		GetFooterHeight() int          // current footer height in lines (0 if no footer)
24		RenderFooter(width int) string // rendered footer content
25	}
26	
27	// FramelessView is implemented by a view that draws its own frames and wants
28	// none around it. The default — framed — is the safe behavior: a view that
29	// does not implement this is framed like all the others, unlike HeaderView
30	// whose missing half silently renders an empty title.
31	//
32	// Only one view implements it (the dashboard), and that is deliberate: every
33	// other view frames a single object — a table, a form.
34	type FramelessView interface {
35		Frameless() bool
36	}
37	
38	// FrameTrailView is implemented by a view that adds a trail (a breadcrumb, an
39	// identifier) to the viewport's top border, in parentheses right after the
40	// title. The router passes the width the trail may take; the view returns an
41	// already-styled string no wider than that, or "" for none. A trail that is too
42	// wide is dropped, never cut. Frameless views never get one.
43	type FrameTrailView interface {
44		FrameTrail(maxWidth int) string
45	}
46	
47	// headerMinHeight is the fixed header height (without the blank line under it).
48	const headerMinHeight = 7
49	
50	// ASCII logo for the header
51	var logoLines = []string{
52		`    ____            ____            __  `,
53		`   / __ \___ _   __/ __ \___  _____/ /__`,
54		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
55		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
56		`/_____/\___/|___/_____/\___/____/_/|_|  `,
57	}
58	
59	const logoWidth = 40 // max width of a logo line
60	
61	// paletteHintText is the permanent header hint that advertises the command palette
62	// (DEVDESK-109). It sits on the header's last row, flush right.
63	const paletteHintText = "ctrl+p Commands"
64	
65	// renderHeader generates the header (fixed height) and the blank line under it.
66	// The command palette is an overlay (DEVDESK-109): it adds no row here.
67	func (a *App) renderHeader() string {
68		if view, ok := a.views[a.currentView]; ok {
69			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
70				shortcuts := headerView.GetShortcuts()
71				if a.commandMode {
72					shortcuts = a.commandLineShortcuts()
73				}
74				info := headerView.GetHeaderInfo(a.currentContext)
75	
76				return renderHeaderContent(info, shortcuts, a.width) + "\n" + theme.EmptyLineBg(a.width)
77			}
78		}
79	
80		return ""
81	}
82	
83	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
84	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
85	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
86		// Two padding cells are the minimum a row can hold; below that the header
87		// is blank rather than wider than the window.
88		if width < 2 {
89			return strings.Join(blankHeaderRows(width), "\n")
90		}
91		innerWidth := width - 2 // 1 padding each side
92	
93		// Column widths
94		col1Width := innerWidth / 4
95		col3Width := logoWidth
96		// The logo column is fixed-width: drop it when it cannot sit next to the
97		// info column, rather than pushing every row past the window (Rule 108).
98		if innerWidth < col1Width+logoWidth {
99			col3Width = 0
100		}
101		col2Width := innerWidth - col1Width - col3Width
102		if col2Width < 0 {
103			col2Width = 0
104		}
105	
106		// Build column 1: key-value info lines
107		col1Lines := buildInfoLines(info, col1Width)
108	
109		// Build column 2: shortcuts
110		col2Lines := buildShortcutLines(shortcuts, col2Width)
111	
112		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
113		var col3Lines []string
114		if col3Width > 0 {
115			col3Lines = buildLogoLines(col3Width)
116		}
117	
118		// Assemble rows
119		rows := make([]string, headerMinHeight)
120		for i := 0; i < headerMinHeight; i++ {
121			c1 := ""
122			if i < len(col1Lines) {
123				c1 = col1Lines[i]
124			}
125			c2 := ""
126			if i < len(col2Lines) {
127				c2 = col2Lines[i]
128			}
129			c3 := ""
130			if i < len(col3Lines) {
131				c3 = col3Lines[i]
132			}
133	
134			pad := theme.Bg(" ")
135			if i == headerMinHeight-1 {
136				// The hint takes the right end of the shortcut and logo columns.
137				rows[i] = pad + theme.PadWithBg(c1, col1Width) + withPaletteHint(c2, col2Width+col3Width, col2Width) + pad
138				continue
139			}
140			row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
141			rows[i] = row
142		}
143	
144		return strings.Join(rows, "\n")
145	}
146	
147	// withPaletteHint returns a line of exactly width cells: shortcuts on the left,
148	// the palette hint flush right. The shortcuts are clipped to maxShortcuts cells
149	// and to what the hint leaves free; ansi.Truncate cuts on cell boundaries and
150	// never inside an escape sequence.
151	func withPaletteHint(shortcuts string, width, maxShortcuts int) string {
152		hint := ansi.Truncate(theme.ShortcutHintStyle.Render(paletteHintText), width, "")
153		free := min(maxShortcuts, width-lipgloss.Width(hint)-1)
154		if free < 0 {
155			free = 0
156		}
157		left := ansi.Truncate(shortcuts, free, "")
158		gap := width - lipgloss.Width(left) - lipgloss.Width(hint)
159		return left + theme.EmptyLineBg(gap) + hint
160	}
161	
162	// blankHeaderRows returns headerMinHeight background-filled rows of the given width.
163	func blankHeaderRows(width int) []string {
164		rows := make([]string, headerMinHeight)
165		for i := range rows {
166			rows[i] = theme.EmptyLineBg(width)
167		}
168		return rows
169	}
170	
171	// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key.
172	// Lines wider than col1Width are clipped, so a narrow column never overflows into the next one.
173	func buildInfoLines(info []shortcut.HeaderInfo, col1Width int) []string {
174		// Find max key length for alignment
175		maxKeyLen := 0
176		for _, h := range info {
177			if len(h.Key) > maxKeyLen {
178				maxKeyLen = len(h.Key)
179			}
180		}
181	
182		lines := make([]string, headerMinHeight)
183		for i := 0; i < headerMinHeight; i++ {
184			if i < len(info) {
185				// Pad key to maxKeyLen so all ": " align
186				paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
187				label := theme.HeaderKeyStyle.Render(paddedKey + ": ")
188	
189				value := info[i].Value
190				if info[i].Style.GetForeground() != lipgloss.Color("") {
191					value = info[i].Style.Background(theme.ColorBackground).Render(value)
192				} else {
193					value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
194				}
195	
196				lines[i] = label + value
197				if col1Width > 0 {
198					// MaxWidth truncates on rune boundaries and keeps escape sequences intact.
199					lines[i] = lipgloss.NewStyle().MaxWidth(col1Width).Render(lines[i])
200				} else {
201					// No room at all: show nothing rather than overflow.
202					lines[i] = ""
203				}
204			} else {
205				lines[i] = ""
206			}
207		}
208		return lines
209	}
210	
211	// buildShortcutLines builds the shortcut lines for column 2
212	func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
213		// A column with no width shows no shortcut: PadWithBg returns a long line
214		// untouched, so anything rendered here would spill past the window.
215		if len(shortcuts) == 0 || col2Width <= 0 {
216			lines := make([]string, headerMinHeight)
217			for i := range lines {
218				lines[i] = ""
219			}
220			return lines
221		}
222	
223		// Split shortcuts into columns of maxLine items
224		columns := splitArrayIntoChunks(shortcuts, headerMinHeight)
225	
226		// Get rendered lines for each column
227		var allColumnLines [][]string
228		for i, col := range columns {
229			minH := 0
230			if i == 0 {
231				minH = headerMinHeight
232			}
233			allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
234		}
235	
236		// Normalize heights
237		for i := range allColumnLines {
238			for len(allColumnLines[i]) < headerMinHeight {
239				allColumnLines[i] = append(allColumnLines[i], "")
240			}
241		}
242	
243		// Calculate column widths
244		colWidths := make([]int, len(allColumnLines))
245		for ci, colLines := range allColumnLines {
246			for _, line := range colLines {
247				if w := lipgloss.Width(line); w > colWidths[ci] {
248					colWidths[ci] = w
249				}
250			}
251		}
252	
253		sep := "  "
254		sepRendered := theme.Bg(sep)
255	
256		// Build each row
257		result := make([]string, headerMinHeight)
258		for row := 0; row < headerMinHeight; row++ {
259			var line string
260			for ci, colLines := range allColumnLines {
261				if ci > 0 {
262					line += sepRendered
263				}
264				if row < len(colLines) {
265					line += theme.PadWithBg(colLines[row], colWidths[ci])
266				} else {
267					line += theme.EmptyLineBg(colWidths[ci])
268				}
269			}
270			// Clip to the column. PadWithBg cannot do this — it pads a short line and
271			// returns a long one untouched — and a plain slice would cut an escape
272			// sequence in half, which is the hazard Rule 122 is about. MaxWidth
273			// truncates on rune boundaries and leaves the sequences intact.
274			if col2Width > 0 {
275				line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
276			}
277			result[row] = line
278		}
279	
280		return result
281	}
282	
283	// buildLogoLines builds the logo lines for column 3, vertically centered
284	func buildLogoLines(col3Width int) []string {
285		logoStyle := lipgloss.NewStyle().
286			Background(theme.ColorBackground).
287			Foreground(theme.ColorPrimary).
288			Bold(true)
289	
290		lines := make([]string, headerMinHeight)
291		// 5 logo lines in 7 header lines → 1 empty line top and bottom
292		offset := 1
293		for i := 0; i < headerMinHeight; i++ {
294			logoIdx := i - offset
295			if logoIdx >= 0 && logoIdx < len(logoLines) {
296				lines[i] = theme.PadWithBg(logoStyle.Render(logoLines[logoIdx]), col3Width)
297			} else {
298				lines[i] = theme.EmptyLineBg(col3Width)
299			}
300		}
301		return lines
302	}
303	
304	// renderShortcutsColumnLines renders a column of shortcuts as individual lines padded to the same width with background.
305	func renderShortcutsColumnLines(shortcuts shortcut.Shortcuts, minHeight int) []string {
306		if len(shortcuts) == 0 {
307			return nil
308		}
309	
310		lines := shortcuts.ToStrings()
311	
312		// Find max width for uniform padding
313		maxWidth := 0
314		for _, line := range lines {
315			if w := lipgloss.Width(line); w > maxWidth {
316				maxWidth = w
317			}
318		}
319	
320		// Pad each line to the same width with background
321		var result []string
322		for _, line := range lines {
323			result = append(result, theme.PadWithBg(line, maxWidth))
324		}
325	
326		// Add empty lines if minHeight required
327		for len(result) < minHeight {
328			result = append(result, theme.EmptyLineBg(maxWidth))
329		}
330	
331		return result
332	}
333	
334	func splitArrayIntoChunks(arr []shortcut.Shortcut, chunkSize int) []shortcut.Shortcuts {
335		var chunks []shortcut.Shortcuts
336		for i := 0; i < len(arr); i += chunkSize {
337			end := i + chunkSize
338			if end > len(arr) {
339				end = len(arr)
340			}
341			chunks = append(chunks, arr[i:end])
342		}
343		return chunks
344	}
345	
346	// commandLineShortcuts is the header's vocabulary while the command line owns
347	// the keyboard. It replaces the view's own: tab and enter stay in place and
348	// grey out when no row is highlighted (Rule 130).
349	func (a *App) commandLineShortcuts() shortcut.Shortcuts {
350		_, runnable := a.runnableText()
351		return shortcut.Shortcuts{
352			{Key: "↑↓", Description: "Choose"},
353			{Key: "tab", Description: "Complete", Disabled: !a.canComplete()},
354			{Key: "enter", Description: "Open", Disabled: !runnable},
355			{Key: "esc", Description: "Close"},
356		}
357	}
