		c1 := ""
		if i < len(col1Lines) {
			c1 = col1Lines[i]
		}
		c2 := ""
		if i < len(col2Lines) {
			c2 = col2Lines[i]
		}
		c3 := ""
		if i < len(col3Lines) {
			c3 = col3Lines[i]
		}

