8		"github.com/anthnel/devdesk/internal/engine"
9		"github.com/anthnel/devdesk/internal/oci"
10	)
11	
12	// filterStops returns the values `r` cycles through: every group that produced
13	// results, then every individual registry, then off. The group level is what
14	// makes "everything from this Nexus" one keystroke rather than eight.
15	func (b *RegistryBrowser) filterStops() []resultFilter {
16		seenGroup, seenEntry := map[string]bool{}, map[string]bool{}
17		var groups, singles []resultFilter
18		for _, t := range b.tags {
19			entry := b.entryFor(t.EntryKey)
20			if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
21				seenGroup[entry.ParentSlug] = true
22				groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
23			}
24			if !seenEntry[t.EntryKey] {
25				seenEntry[t.EntryKey] = true
26				singles = append(singles, resultFilter{entryKey: t.EntryKey})
27			}
28		}
29		// A single source has nothing to filter down to.
30		if len(singles) <= 1 {
31			return nil
32		}
33		// A group with every result under it says the same thing as "off".
34		if len(groups) == 1 && len(groups) == len(seenGroup) && len(singles) == countMembers(b.entries, groups[0].groupSlug) {
35			groups = nil
36		}
37		return append(groups, singles...)
38	}
39	
40	// countMembers returns how many entries belong to a group.
41	func countMembers(entries []browserRegistryEntry, slug string) int {
42		n := 0
43		for _, e := range entries {
44			if e.ParentSlug == slug {
45				n++
46			}
47		}
48		return n
49	}
50	
51	func (b *RegistryBrowser) cycleRegistryFilter() {
52		stops := b.filterStops()
53		if len(stops) == 0 {
54			b.registryFilter = resultFilter{}
55			b.rebuildTagTable()
56			return
57		}
58		if b.registryFilter.isEmpty() {
59			b.registryFilter = stops[0]
60			b.rebuildTagTable()
61			return
62		}
63		for i, s := range stops {
64			if s == b.registryFilter {
65				if i+1 < len(stops) {
66					b.registryFilter = stops[i+1]
67				} else {
68					b.registryFilter = resultFilter{} // back to everything
69				}
70				b.rebuildTagTable()
71				return
72			}
73		}
74		b.registryFilter = resultFilter{}
75		b.rebuildTagTable()
76	}
77	
78	// entryFor returns the browser entry a result came from, or nil.
79	//
80	// It resolves by entry key, not by URL: every member of a path-routed group
81	// answers to the same host, so a URL identifies a whole instance and a result
82	// would be unattributable (§3.18, and D40 one screen along).
83	func (b *RegistryBrowser) entryFor(key string) *browserRegistryEntry {
84		for i := range b.entries {
85			if b.entries[i].key == key {
86				return &b.entries[i]
87			}
88		}
89		return nil
90	}
91	
92	// registryFilterLabel returns a short display label for the active filter.
93	//
94	// D14: it used to search only the configured top-level entries, so filtering to
95	// a discovered member fell through to the synthesised URL — the one row in the
96	// view showing a URL where every other showed an alias. Members are entries now,
97	// so they resolve like anything else.
98	func (b *RegistryBrowser) registryFilterLabel() string {
99		if b.registryFilter.groupSlug != "" {
100			for _, reg := range b.registries {
101				if reg.Slug == b.registryFilter.groupSlug {
102					return browserAlias(reg)
103				}
104			}
105			return b.registryFilter.groupSlug
106		}
107		if entry := b.entryFor(b.registryFilter.entryKey); entry != nil {
108			if entry.ParentAlias != "" {
109				return entry.ParentAlias + "/" + entry.Alias
110			}
111			if entry.Alias != "" {
112				return entry.Alias
113			}
114			return registryRef(entry.URL, entry.repoPrefix)
115		}
116		return b.registryFilter.entryKey
117	}
118	
119	// pullSelectedTag asks the parent to admit the pull as a job, mirroring
120	// requestDirectScan below.
121	//
122	// It holds no state of its own for it any more (§3.60). The browser used to
123	// take over the screen with a spinner of its own until the pull answered,
124	// which said less than the Images tab now does — the row is there, spinning,
125	// next to every other image — and said it on the one screen from which the
